require_once __DIR__.'/includes/faculty_views.php';
$db=portalDb();$u=portalUser($db,'professor');$view=(string)($_GET['view']??'classes');$id=(int)($_GET['subject_id']??0);$error='';
// Criteria now live in Class settings; the old address still works.
if($view==='criteria')$view='settings';
if($_SERVER['REQUEST_METHOD']==='POST'){try{portalCsrf();$posted=(string)($_POST['action']??'');$id=cbProfessorAction($db,$u,$posted);
    $sheetContext=match($posted){'save_scores','edit_activity'=>'&activity_id='.(int)($_POST['activity_id']??0),'save_attendance','edit_meeting'=>'&meeting_id='.(int)($_POST['meeting_id']??0),default=>''};
    if($posted==='take_attendance_today'&&isset($_SESSION['cb_created'])){[$key,$created]=$_SESSION['cb_created'];$sheetContext='&'.$key.'='.(int)$created;}
    unset($_SESSION['cb_created']);
    $message='Saved successfully.';
    if($posted==='enroll_many'&&isset($_SESSION['cb_enrolled'])){[$added,$skipped]=$_SESSION['cb_enrolled'];unset($_SESSION['cb_enrolled']);$message='Saved successfully. '.$added.' enrolled'.($skipped?', '.$skipped.' already in this class':'').'.';}
    portalRedirect('professor-dashboard.php?view='.urlencode($view).'&subject_id='.$id.$sheetContext,$message);}catch(Throwable $e){$error=portalError($e);}}
$classes=cbQuery($db,"SELECT s.*,c.state,c.revision,c.archived,(SELECT COUNT(*) FROM enrollments e LEFT JOIN classbook_members m ON m.enrollment_id=e.id WHERE e.subject_id=s.id AND COALESCE(m.status,'active')='active') AS student_count FROM subjects s LEFT JOIN classbook_settings c ON c.subject_id=s.id WHERE professor_id=? ORDER BY s.id DESC",[$u['id']])->fetchAll();
$s=null;foreach($classes as $row)if((int)$row['id']===$id)$s=$row;
$pageInfo=match($view){
'attendance'=>['Attendance','Take attendance for a class meeting. Everyone starts as Present.'],
'activities'=>['Scores','Add a quiz, activity or exam and type each student\'s score.'],
'grades'=>['Grades','Check the computed grades, then submit the grade sheet to the Registrar.'],
'import'=>['Import online attendance','Upload a Meet or CSV attendance report and confirm the matches.'],
'settings'=>['Class settings','Grading criteria, attendance points and grade conversion.'],
'roster'=>['Students','Students enrolled in this class.'],
default=>['My classes','Open a class to take attendance, record scores and submit grades.']};
portalStart($pageInfo[0],$u,$view);portalHeading($pageInfo[0],$pageInfo[1]);if($error)portalNotice($error,'danger');
if($view==='classes'||!in_array($view,['attendance','activities','grades','import','settings','roster'],true)){
    cbFacultyClassDirectory($classes);portalEnd();exit;
}
if(!$s){cbFacultyClassDirectory($classes,$view);portalEnd();exit;}
if($s['revision']===null){?><form method="post" class="card"><?php portalPost('initialize_class');?><input type="hidden" name="subject_id" value="<?=$id?>"><p>Start individual records for this legacy class. Existing totals remain in the database and are not converted into invented activities.</p><button>Initialize class record</button></form><?php portalEnd();exit;}
$s=cbClass($db,$id,$u);$locked=$s['state']!=='draft'||$s['archived'];$disabled=$locked?'disabled':'';$criteria=cbClassCriteria($db,$id);$classGroups=cbClassGroups($db,$id);$members=cbMembers($db,$id);$options=[];foreach($criteria as $c)$options[$c['id']]=$classGroups[$c['group_key']].' · '.$c['name'];
cbFacultyClassContext($s,$view);
if($locked)portalNotice('This class is locked. The Registrar must return it for correction before changes can be saved.');
if($view==='settings'){
    cbFacultySettings($db,$s,$classes,$criteria,$classGroups,$disabled);
}elseif($view==='roster'){
    $all=cbMembers($db,$id,false);
    ?><section class="card"><div class="panel-heading"><div><h2>Enrolled students</h2><p class="muted">Dropping keeps the student's records; you can restore them later.</p></div><span class="pill"><?=count($members)?> active</span></div><?php if($all):?><label class="field">Find student<input data-search-table="#roster-table" type="search" placeholder="Student number or name"></label><div class="table-wrap" tabindex="0" role="region" aria-label="Enrolled students"><table id="roster-table"><thead><tr><th>Student</th><th>Number</th><th>Starts</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($all as $m):$name=$m['last_name'].', '.$m['first_name'];?><tr><td><?=h($name)?></td><td><?=h($m['student_no'])?></td><td><?=h($m['starts_on'])?></td><td><span class="pill"><?=h(ucfirst($m['enrollment_status']))?></span></td><td><form method="post" class="inline-action"><?php if($m['enrollment_status']==='active'){portalPost('drop_enrollment',$s);?><input type="hidden" name="enrollment_id" value="<?=$m['enrollment_id']?>"><button class="icon-action" <?=$disabled?> data-confirm="<?=h('Drop '.$name.' from this class? Their records are kept.')?>" aria-label="<?=h('Drop '.$name)?>" title="Drop student"><?=portalIcon('user-minus')?></button><?php }else{portalPost('restore_enrollment',$s);?><input type="hidden" name="enrollment_id" value="<?=$m['enrollment_id']?>"><input type="hidden" name="reason" value="Restored by professor"><button class="icon-action" <?=$disabled?> aria-label="<?=h('Restore '.$name)?>" title="Restore student"><?=portalIcon('user-plus')?></button><?php }?></form></td></tr><?php endforeach;?></tbody></table></div><?php else:?><p>No students yet. Paste their student numbers below.</p><?php endif;?></section>
    <form method="post" class="card"><?php portalPost('enroll_many',$s);?><h2>Add students</h2><p class="muted">Paste student numbers from your class list — one per line, or separated by commas. Students already in the class are skipped.</p><label class="field">Student numbers<textarea name="student_numbers" rows="5" required placeholder="2026-00001&#10;2026-00002"></textarea></label><div class="form-grid"><?php portalField('Counted from (enrollment date)','starts_on',date('Y-m-d'),'date','required');?></div><button <?=$disabled?>><?=portalIcon('user-plus')?>Add students</button></form>
    <details class="card collapsible-card"><summary>Add one student without an account</summary><form method="post"><?php portalPost('enroll',$s);?><p class="muted">Use this only when the student has no account yet. The Registrar activates new accounts.</p><div class="form-grid"><?php portalField('Student number','student_no','','text','required');portalField('First name','first_name');portalField('Last name','last_name');portalField('Email (optional)','email','','email');portalField('Counted from','starts_on',date('Y-m-d'),'date','required');?></div><button <?=$disabled?>>Add student</button></form></details><?php
}elseif($view==='activities'){
    require_once __DIR__.'/includes/faculty_records.php';cbFacultyActivityRecords($db,$s,$members,$criteria,$options);
}elseif($view==='attendance'){
    require_once __DIR__.'/includes/faculty_records.php';cbFacultyAttendanceRecords($db,$s,$members,$criteria,$options);
}elseif($view==='import'){
$attOptions=[];foreach($criteria as $c)if($c['kind']==='attendance')$attOptions[$c['id']]=$options[$c['id']];
?><div class="actions"><a class="button secondary" href="<?=h('professor-dashboard.php?view=attendance&subject_id='.$id)?>"><?=portalIcon('arrow-right')?>Back to attendance</a></div><link rel="stylesheet" href="assets/css/file-upload.css?v=<?=filemtime(__DIR__.'/assets/css/file-upload.css')?>"><form method="post" enctype="multipart/form-data" class="card attendance-import-form"><?php portalPost('preview_import',$s);?><h2>Import online attendance</h2><p>Upload a CSV attendance export or a supported Meet Attendance Tracker PDF. Students are matched automatically by student number or email; you only fix the rows that could not be matched.</p><div class="form-grid"><?php portalSelect('Period','criterion_id',$attOptions,cbFacultyCurrentAttendance($criteria,$classGroups));portalField('Meeting date','meeting_date',date('Y-m-d'),'date','required');?></div><div class="attendance-file" data-attendance-file><div class="attendance-file-heading"><span class="attendance-file-icon"><?=portalIcon('file-text')?></span><div><label for="attendance-report">Attendance report</label><p id="attendance-report-help">CSV or Meet Attendance Tracker PDF</p></div></div><input id="attendance-report" type="file" name="report" accept=".pdf,.csv" required aria-describedby="attendance-report-help attendance-file-status"><p class="attendance-file-status" id="attendance-file-status" data-file-status role="status" aria-live="polite">No file selected. Choose your attendance report to continue.</p></div><p class="attendance-import-format">Present/Late/Absent is decided from the minutes attended using the thresholds in Class settings. Scanned PDFs are not supported. Students missing from the report stay unrecorded.</p><button <?=$disabled?>><?=portalIcon('file-check-2')?>Read and preview</button></form><script src="assets/js/file-upload.js?v=<?=filemtime(__DIR__.'/assets/js/file-upload.js')?>"></script><?php
$d=$_SESSION['classbook_import']??null;if($d&&(int)$d['subject']===$id&&(int)$d['actor']===(int)$u['id']){$unmatched=0;?><form method="post" class="card"><?php portalPost('commit_import',$s);?><h3>Review <?=h($d['filename'])?></h3><p>Date <?=h($d['date'])?> · Report accuracy <?=h($d['report']['accuracy']??'Not provided')?>.</p><div class="table-wrap" tabindex="0" role="region" aria-label="Imported attendance"><table><tr><th>Reported participant</th><th>Minutes</th><th>Enrolled student</th><th>Status</th></tr><?php foreach($d['report']['rows'] as $i=>$r){$opts=[''=>'Choose student','skip'=>'Skip this row'];$match='';foreach($members as $m){$opts[$m['enrollment_id']]=$m['student_no'].' · '.$m['last_name'].', '.$m['first_name'];if(($r['kind']==='number'&&($r['identity']===$m['student_no']||$r['identity']===($m['public_id']??'')))||($r['kind']==='email'&&strcasecmp($r['identity'],$m['email']??'')===0))$match=$m['enrollment_id'];}if($match==='')$unmatched++;$status='';if($s['online_full_minutes']!==null)$status=$r['seconds']>=$s['online_full_minutes']*60?'present':($r['seconds']>=$s['online_partial_minutes']*60?'late':'absent');?><tr><td><?=h($r['identity'])?></td><td><?=h(round($r['seconds']/60,2))?></td><td><?php portalSelect('Match','matches['.$i.']',$opts,$match);?></td><td><?php portalSelect('Status','statuses['.$i.']',[''=>'Choose status','present'=>'Present','late'=>'Late / partial','absent'=>'Absent','excused'=>'Excused'],$status);?></td></tr><?php }?></table></div><?php portalNotice($unmatched?$unmatched.' row(s) need a student match or Skip.':'All rows were matched automatically. Check and confirm.',$unmatched?'danger':'info');if($d['report']['format']==='tracker_pdf'):?><label><input type="checkbox" name="quality_reviewed" value="1" required>I reviewed report accuracy and matched identities.</label><?php endif;?><button <?=$disabled?>>Confirm import</button></form><?php }
}elseif($view==='grades'){
    cbFacultyGrades($db,$s,$disabled);
